fun render(user: User?) {
    user?.let { u ->
        println("${u.name} <${u.email ?: "no-email"}>")
    } ?: run {
        println("no user selected")
    }
}

fun tally(lines: List<String>): Map<String, Int> =
    lines
        .flatMap { it.split(Regex("\\s+")) }
        .filter { it.isNotBlank() }
        .groupingBy { it.lowercase() }
        .eachCount()

suspend fun load(id: String): Result<User> = withContext(Dispatchers.IO) {
    when (val res = api.fetch(id)) {
        is Ok -> Result.success(res.value)
        is Err -> Result.failure(IllegalStateException(res.message ?: "unknown"))
    }
}

sealed interface Shape {
    data class Circle(val radius: Double) : Shape
    data class Rect(val w: Double, val h: Double) : Shape
}

fun area(shape: Shape): Double = when (shape) {
    is Shape.Circle -> Math.PI * shape.radius * shape.radius
    is Shape.Rect -> shape.w * shape.h
}

fun ticks(period: Long): Flow<Int> = flow {
    var n = 0
    while (true) {
        emit(n++)
        delay(period)
    }
}.flowOn(Dispatchers.Default)

suspend fun collectTicks(scope: CoroutineScope) = scope.launch {
    ticks(250).take(10).collect { println("tick $it") }
}

