suspend fun <T> retry(
    attempts: Int = 3,
    initialDelay: Long = 250,
    block: suspend () -> T,
): T {
    var delayMs = initialDelay
    repeat(attempts - 1) {
        try {
            return block()
        } catch (e: IOException) {
            delay(delayMs)
            delayMs *= 2
        }
    }
    return block()
}

class DrillViewModel(private val repo: DrillRepo) {

    private val _state = MutableStateFlow<UiState>(UiState.Loading)
    val state: StateFlow<UiState> = _state.asStateFlow()

    fun refresh(scope: CoroutineScope) = scope.launch {
        _state.value = when (val result = repo.load()) {
            is Ok -> UiState.Ready(result.value)
            is Err -> UiState.Failed(result.message ?: "unknown error")
        }
    }
}

inline fun <T, K> Iterable<T>.groupByTo(
    destination: MutableMap<K, MutableList<T>>,
    keySelector: (T) -> K,
): MutableMap<K, MutableList<T>> {
    for (element in this) {
        destination.getOrPut(keySelector(element)) { mutableListOf() }.add(element)
    }
    return destination
}

fun <T> List<T>.chunkedPairs(): List<Pair<T, T?>> =
    chunked(2).map { it.first() to it.getOrNull(1) }

data class Page<T>(val items: List<T>, val cursor: String? = null)

suspend fun <T> fetchAll(
    fetch: suspend (String?) -> Page<T>,
): List<T> = buildList {
    var cursor: String? = null
    do {
        val page = fetch(cursor)
        addAll(page.items)
        cursor = page.cursor
    } while (cursor != null)
}

sealed class Cmd {
    data class Run(val lang: String, val minutes: Int) : Cmd()
    data object Help : Cmd()
    data class Unknown(val raw: String) : Cmd()
}

fun parse(args: List<String>): Cmd = when {
    args.isEmpty() -> Cmd.Help
    args.first() == "run" -> Cmd.Run(
        lang = args.getOrNull(1) ?: "rust",
        minutes = args.getOrNull(2)?.toIntOrNull() ?: 10,
    )
    else -> Cmd.Unknown(args.joinToString(" "))
}
